// T-57 spike: deck-level checks of MCM's Modern metagame deck scenarios, run against
// ironsmith's WASM engine. Copied by the spike workflow into scripts/spike-t57/ of an
// ironsmith checkout, next to the modules generated by spike/translate.py.
//
// Each MCM deck test maps to one or more check kinds (see spike/translate.py NAME_RULES).
// Player 0 plays the MCM pilot's deck, player 1 the opponent deck MCM registers.
import test from "node:test";
import { appendFileSync } from "node:fs";
import {
  assert,
  ensureCardSourcesForNames,
  getHand,
  getInspectionState,
  getLibrary,
  initWasmRuntime,
} from "../wasm-test-harness.mjs";
import { normalizePhase } from "../mage-port-runner/names.mjs";

const PLAYER_NAMES = ["Alice", "Bob"];
const HAND = 7;

function detail(record) {
  const path = process.env.SPIKE_DETAILS;
  if (path) appendFileSync(path, `${JSON.stringify(record)}\n`);
}

function frontFace(name) {
  return String(name ?? "").split(" // ")[0].trim();
}

function matchConfig(spec, seed) {
  return {
    playerNames: PLAYER_NAMES,
    startingLife: 20,
    seed,
    format: "normal",
    startingPlayer: 0,
    decks: spec.decks.map((deck) => deck.main),
    sideboards: spec.decks.map((deck) => deck.side),
    openingHandSize: HAND,
  };
}

async function newGame() {
  const runtime = await initWasmRuntime({ pkg: "root" });
  return new runtime.wasmModule.WasmGame();
}

function free(game) {
  try {
    game?.free?.();
  } catch {
    // already released
  }
}

async function started(spec, seed) {
  const game = await newGame();
  game.startMatch(matchConfig(spec, seed));
  return game;
}

function dealt(game, player) {
  const checkpoint = getInspectionState(game);
  const hand = getHand(checkpoint, player);
  const library = getLibrary(checkpoint, player);
  return { checkpoint, hand, library, all: [...hand, ...library] };
}

function multiset(names) {
  const counts = new Map();
  for (const name of names) counts.set(name, (counts.get(name) ?? 0) + 1);
  return [...counts.entries()].sort(([a], [b]) => a.localeCompare(b));
}

async function advanceToFirstMain(game) {
  for (let step = 0; step < 400; step += 1) {
    const state = game.uiState();
    if (Number(state.turn_number) === 1 && normalizePhase(state.phase, state.step) === "PRECOMBAT_MAIN") {
      return state;
    }
    const decision = state.decision;
    if (!decision) {
      game.dispatch({ type: "continue" });
    } else if (decision.kind === "priority") {
      const pass = (decision.actions || []).find(
        (action) =>
          action.kind === "pass_priority" ||
          action.action_ref?.kind === "pass_priority" ||
          ["Keep hand", "Pregame", "Continue", "Begin game"].includes(action.label),
      );
      assert(pass, "no pass or keep action while advancing to the first main phase", decision);
      game.dispatch({ type: "priority_action", action_index: pass.index });
    } else {
      throw new Error(`unexpected decision while advancing to main: ${decision.kind}`);
    }
  }
  throw new Error("did not reach turn 1 precombat main");
}

const CHECKS = {
  async cards_known(spec, ctx) {
    const game = await newGame();
    try {
      const config = matchConfig(spec, 1);
      // validateMatchConfig is not instrumented by the harness; register the card sources
      // the lean build loads from web/ui/public/cards first, as startMatch does.
      ensureCardSourcesForNames(game, [...config.decks.flat(), ...config.sideboards.flat()]);
      const result = game.validateMatchConfig(config);
      const issues = (result.issues || []).filter((issue) => Number(issue.player_index ?? issue.playerIndex) === 0);
      detail({ kind: "cards_known", source: spec.sourcePath, test: ctx.name, issues });
      assert(issues.length === 0, `${issues.length} card(s) of the list are not playable in ironsmith`, issues);
    } finally {
      free(game);
    }
  },
  async opening_hand(spec) {
    const game = await started(spec, 1);
    try {
      const { hand, library } = dealt(game, 0);
      assert(hand.length === HAND, `expected 7 cards in hand, got ${hand.length}`);
      const rest = spec.decks[0].main.length - HAND;
      assert(library.length === rest, `expected ${rest} cards in library, got ${library.length}`);
    } finally {
      free(game);
    }
  },
  async opening_hand_both(spec) {
    const game = await started(spec, 1);
    try {
      for (const player of [0, 1]) {
        const { hand, library } = dealt(game, player);
        assert(hand.length === HAND, `player ${player}: expected 7 in hand, got ${hand.length}`);
        const rest = spec.decks[player].main.length - HAND;
        assert(library.length === rest, `player ${player}: expected ${rest} in library, got ${library.length}`);
        const own = new Set(spec.decks[player].main.map(frontFace));
        const foreign = dealt(game, player).all.filter((object) => !own.has(frontFace(object.name)));
        assert(foreign.length === 0, `player ${player} was dealt cards from outside their list`, foreign.map((o) => o.name));
      }
    } finally {
      free(game);
    }
  },
  async starting_life(spec) {
    const game = await started(spec, 1);
    try {
      const checkpoint = getInspectionState(game);
      for (const player of checkpoint.players) {
        assert(Number(player.life) === 20, `player ${player.id} starts at ${player.life}, not 20`);
      }
    } finally {
      free(game);
    }
  },
  async sideboard_aside(spec) {
    const game = await started(spec, 1);
    try {
      const { all } = dealt(game, 0);
      const main = new Set(spec.decks[0].main.map(frontFace));
      const sideOnly = spec.decks[0].side.map(frontFace).filter((name) => !main.has(name));
      const leaked = all.filter((object) => sideOnly.includes(frontFace(object.name)));
      assert(leaked.length === 0, "sideboard-only cards were shuffled into hand or library", leaked.map((o) => o.name));
      assert(all.length === spec.decks[0].main.length, `expected ${spec.decks[0].main.length} cards in hand and library, got ${all.length}`);
    } finally {
      free(game);
    }
  },
  async dealt_is_registered(spec) {
    const game = await started(spec, 1);
    try {
      const { all } = dealt(game, 0);
      const actual = JSON.stringify(multiset(all.map((object) => frontFace(object.name))));
      const expected = JSON.stringify(multiset(spec.decks[0].main.map(frontFace)));
      assert(actual === expected, "the dealt sixty is not the registered sixty", { actual, expected });
    } finally {
      free(game);
    }
  },
  async distinct_objects(spec) {
    const game = await started(spec, 1);
    try {
      const { all } = dealt(game, 0);
      const ids = new Set(all.map((object) => String(object.id)));
      assert(ids.size === spec.decks[0].main.length, `expected ${spec.decks[0].main.length} distinct objects, got ${ids.size}`);
    } finally {
      free(game);
    }
  },
  async ownership(spec) {
    const game = await started(spec, 1);
    try {
      for (const player of [0, 1]) {
        const { all } = dealt(game, player);
        const wrong = all.filter((object) => Number(object.owner) !== player);
        assert(wrong.length === 0, `player ${player} holds cards owned by someone else`, wrong.map((o) => o.name));
      }
    } finally {
      free(game);
    }
  },
  async shuffle(spec) {
    const order = async (seed) => {
      const game = await started(spec, seed);
      try {
        return dealt(game, 0).all.map((object) => frontFace(object.name)).join("|");
      } finally {
        free(game);
      }
    };
    const one = await order(1);
    const again = await order(1);
    const two = await order(2);
    assert(one === again, "the same seed dealt a different order");
    assert(one !== two, "two seeds dealt the same order");
    const listed = spec.decks[0].main.map(frontFace).join("|");
    assert(one !== listed, "the library is in registered list order");
  },
  async first_draw_skipped(spec) {
    const game = await started(spec, 1);
    try {
      await advanceToFirstMain(game);
      const { hand } = dealt(game, 0);
      assert(hand.length === HAND, `starting player has ${hand.length} cards in turn 1 main, expected 7`);
    } finally {
      free(game);
    }
  },
};

export function registerDeckChecks(spec) {
  for (const check of spec.checks) {
    test(`${spec.sourcePath} :: ${check.name}`, async () => {
      for (const kind of check.kinds) {
        const run = CHECKS[kind];
        assert(run, `unknown check kind ${kind}`);
        await run(spec, check);
      }
    });
  }
}
